namespace ArcaneCore.Atlas.Textures;

/// <summary>
/// A decoded BLP: the validated <see cref="Header"/> and the whole mip chain, level 0 first, down to 1x1. Levels the file does
/// not hold (<c>Header.ValidLevelCount</c> and beyond) are generated by a box filter from the level before them.
/// </summary>
public sealed class BlpImage
{
    internal BlpImage(BlpFile header, IReadOnlyList<RgbaImage> levels)
    {
        Header = header;
        Levels = levels;
    }

    public BlpFile Header { get; }

    public IReadOnlyList<RgbaImage> Levels { get; }

    /// <summary>True when the image has per-pixel transparency.</summary>
    public bool HasAlpha => Header.HasAlpha;

    /// <summary>True when the transparency is a single bit (cut-out textures).</summary>
    public bool Alpha1Bit => Header.HasAlpha && Header.Alpha1Bit;

    /// <summary>Bytes of pixel data held by all levels.</summary>
    public long PixelBytes => Levels.Sum(l => (long)l.Pixels.Length);
}

/// <summary>
/// Decodes BLP2 files (palettized with 0, 1, 4 or 8 bit alpha, DXT1, DXT3, DXT5 and raw BGRA) to RGBA8. Palettized alpha comes
/// from <c>alphaDepth</c> only, never from the palette's alpha byte or <c>alphaType</c>; a DXT1 transparent index is honoured only
/// when <c>alphaDepth</c> is 1. Pure; any thread. Failures are <see cref="InvalidDataException"/> only.
/// </summary>
public static class BlpDecoder
{
    public static BlpImage Decode(byte[] file)
    {
        BlpFile header = BlpFile.Parse(file);
        var levels = new List<RgbaImage>(header.FullLevelCount);
        for (int i = 0; i < header.ValidLevelCount; i++)
        {
            (int w, int h) = header.LevelSize(i);
            levels.Add(new RgbaImage(w, h, DecodeLevel(header, i, w, h)));
        }

        for (int i = header.ValidLevelCount; i < header.FullLevelCount; i++)
        {
            levels.Add(BoxDown(levels[i - 1]));
        }

        return new BlpImage(header, levels);
    }

    /// <summary>The next smaller level: each texel is the alpha-weighted average of a 2x2 block (plain average when the block is fully transparent).</summary>
    public static RgbaImage BoxDown(RgbaImage source)
    {
        ArgumentNullException.ThrowIfNull(source);
        int width = Math.Max(1, source.Width >> 1);
        int height = Math.Max(1, source.Height >> 1);
        byte[] output = new byte[width * height * 4];
        byte[] src = source.Pixels;
        for (int y = 0; y < height; y++)
        {
            int y0 = Math.Min(y * 2, source.Height - 1);
            int y1 = Math.Min((y * 2) + 1, source.Height - 1);
            for (int x = 0; x < width; x++)
            {
                int x0 = Math.Min(x * 2, source.Width - 1);
                int x1 = Math.Min((x * 2) + 1, source.Width - 1);
                int p0 = ((y0 * source.Width) + x0) * 4;
                int p1 = ((y0 * source.Width) + x1) * 4;
                int p2 = ((y1 * source.Width) + x0) * 4;
                int p3 = ((y1 * source.Width) + x1) * 4;
                int a0 = src[p0 + 3], a1 = src[p1 + 3], a2 = src[p2 + 3], a3 = src[p3 + 3];
                int alphaSum = a0 + a1 + a2 + a3;
                int at = ((y * width) + x) * 4;
                for (int c = 0; c < 3; c++)
                {
                    output[at + c] = alphaSum == 0
                        ? (byte)((src[p0 + c] + src[p1 + c] + src[p2 + c] + src[p3 + c] + 2) >> 2)
                        : (byte)(((src[p0 + c] * a0) + (src[p1 + c] * a1) + (src[p2 + c] * a2) + (src[p3 + c] * a3) + (alphaSum / 2)) / alphaSum);
                }

                output[at + 3] = (byte)((alphaSum + 2) >> 2);
            }
        }

        return new RgbaImage(width, height, output);
    }

    private static byte[] DecodeLevel(BlpFile header, int level, int width, int height)
    {
        ReadOnlySpan<byte> data = header.LevelSpan(level);
        switch (header.Compression)
        {
            case 1:
                return DecodePalettized(header, data, width, height);
            case 2:
                return header.AlphaType switch
                {
                    0 => DxtCodec.DecodeDxt1(data, width, height, keepTransparency: header.AlphaDepth == 1),
                    1 => DxtCodec.DecodeDxt3(data, width, height),
                    _ => DxtCodec.DecodeDxt5(data, width, height),
                };
            default:
                return DecodeRaw(header, data, width, height);
        }
    }

    private static byte[] DecodePalettized(BlpFile header, ReadOnlySpan<byte> data, int width, int height)
    {
        int pixels = width * height;
        byte[] output = new byte[pixels * 4];
        Span<byte> palette = stackalloc byte[256 * 3];
        for (int i = 0; i < 256; i++)
        {
            (byte r, byte g, byte b) = header.PaletteColour(i);
            palette[(3 * i)] = r;
            palette[(3 * i) + 1] = g;
            palette[(3 * i) + 2] = b;
        }

        ReadOnlySpan<byte> plane = data[pixels..];
        for (int i = 0; i < pixels; i++)
        {
            int index = data[i];
            int at = i * 4;
            output[at] = palette[3 * index];
            output[at + 1] = palette[(3 * index) + 1];
            output[at + 2] = palette[(3 * index) + 2];
            output[at + 3] = header.AlphaDepth switch
            {
                1 => (byte)(((plane[i >> 3] >> (i & 7)) & 1) != 0 ? 255 : 0),
                4 => (byte)(((plane[i >> 1] >> ((i & 1) * 4)) & 0xF) * 17),
                8 => plane[i],
                _ => 255,
            };
        }

        return output;
    }

    private static byte[] DecodeRaw(BlpFile header, ReadOnlySpan<byte> data, int width, int height)
    {
        int pixels = width * height;
        byte[] output = new byte[pixels * 4];
        bool hasAlpha = header.AlphaDepth != 0;
        for (int i = 0; i < pixels; i++)
        {
            int at = i * 4;
            output[at] = data[at + 2];
            output[at + 1] = data[at + 1];
            output[at + 2] = data[at];
            output[at + 3] = hasAlpha ? data[at + 3] : (byte)255;
        }

        return output;
    }
}
